    #[test]
    fn a_new_session_announces_the_same_grant_again() {
        // Sign out and back in with the very grant announced before: the
        // sign-in-required forgot it, so the new session announces it.
        let granted = SEEDED.join(" ");
        let (events, dir, handle, _srv) = startup_events(
            "scopes-new-session",
            vec![
                (
                    token_route(&format!(
                        r#"{{"access_token":"AT2","refresh_token":"RT2","expires_in":3600,"scope":"{granted}"}}"#
                    )),
                    None,
                ),
                (empty_folders_route(200), None),
            ],
            test_cfg(),
            |p| seed_token_with_scopes(p, 3600, SEEDED),
        );
        assert_eq!(scopes_events(&events).len(), 1, "{events:?}");
        handle.cmd_tx.send(SyncCommand::SignOut).unwrap();
        wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::SignInRequired));
        sign_in_through_loopback(&handle);
        let events = wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::FoldersUpdated));
        assert_eq!(
            scopes_events(&events),
            vec![(strings(SEEDED), Vec::new())],
            "{events:?}"
        );
        finish(handle, dir);
    }

    #[test]
    fn sign_in_refused_reports_error_description() {
        let srv = FakeServer::start(vec![token_route(
            r#"{"access_token":"AT","refresh_token":"RT","expires_in":3600}"#,
        )]);
        let base = srv.base_url.clone();
        let dir = unique_dir("signin-refused");
        let token_path = dir.join("token.bin");
        let handle = spawn_with_bases(
            dir.join("mail.db"),
            token_path.clone(),
            test_cfg(),
            3650,
            base.clone(),
            base,
            Duration::from_secs(3600),
        );
        wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::SignInRequired));
        let (_, response) = sign_in_through_loopback_with(&handle, |state| {
            format!(
                "error=consent_required&error_description=AADSTS65001%3A+The+user+or+administrator+has+not+consented%0D%0ATrace+ID%3A+abc&state={state}"
            )
        });
        assert!(response.to_lowercase().contains("failed"));
        let events = wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::SignInRequired));
        assert!(
            events.contains(&SyncEvent::Error(
                "sign-in failed: authorization denied: consent_required: AADSTS65001: The user or administrator has not consented Trace ID: abc"
                    .into()
            )),
            "{events:?}"
        );
        assert!(tokencache::load(&token_path).unwrap().is_none());
        finish(handle, dir);
    }

    /// `handle_redirect` over a real loopback connection that sends
    /// `GET /?<query>`.
    fn redirect_result(query: &str, expected_state: &str) -> Result<String, String> {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let port = listener.local_addr().unwrap().port();
        let mut client = TcpStream::connect(("127.0.0.1", port)).unwrap();
        client
            .write_all(format!("GET /?{query} HTTP/1.1\r\nHost: localhost\r\n\r\n").as_bytes())
            .unwrap();
        let (stream, _addr) = listener.accept().unwrap();
        let result = handle_redirect(stream, expected_state);
        drop(client);
        result
    }

    const REFUSED: &str = "error=consent_required&error_description=AADSTS65001%3A+The+user+or+administrator+has+not+consented%0D%0ATrace+ID%3A+abc%0D%0A";

    #[test]
    fn handle_redirect_reports_error_description() {
        assert_eq!(
            redirect_result(&format!("{REFUSED}&state=st"), "st"),
            Err(
                "authorization denied: consent_required: AADSTS65001: The user or administrator has not consented Trace ID: abc"
                    .to_string()
            )
        );
        // An empty (or blank) description keeps the bare error.
        assert_eq!(
            redirect_result(
                "error=access_denied&error_description=+%0D%0A&state=st",
                "st"
            ),
            Err("authorization denied: access_denied".to_string())
        );
        assert_eq!(
            redirect_result("error=access_denied&state=st", "st"),
            Err("authorization denied: access_denied".to_string())
        );
    }

    #[test]
    fn handle_redirect_hides_free_text_error_on_a_state_mismatch() {
        // An `error` that is not a bare code is free text too.
        let phishing = "error=Your+account+is+locked.+Call+%2B1-800-555-0100";
        assert_eq!(
            redirect_result(phishing, "st"),
            Err("authorization denied (redirect state did not match)".to_string())
        );
        assert_eq!(
            redirect_result(&format!("{phishing}&state=wrong"), "st"),
            Err("authorization denied (redirect state did not match)".to_string())
        );
        assert_eq!(
            redirect_result("error=consent_required%0D%0A&state=wrong", "st"),
            Err("authorization denied (redirect state did not match)".to_string())
        );
        // A bare code is shown as before.
        assert_eq!(
            redirect_result("error=consent_required&state=wrong", "st"),
            Err("authorization denied: consent_required".to_string())
        );
        // With our state, `error` is shown, on one line.
        assert_eq!(
            redirect_result("error=server+error%0D%0Aretry+later&state=st", "st"),
            Err("authorization denied: server error retry later".to_string())
        );
    }

    #[test]
    fn handle_redirect_drops_error_description_on_a_state_mismatch() {
        // Anything can send the browser here: free text only with our state.
        assert_eq!(
            redirect_result(&format!("{REFUSED}&state=wrong"), "st"),
            Err("authorization denied: consent_required".to_string())
        );
        assert_eq!(
            redirect_result(REFUSED, "st"),
            Err("authorization denied: consent_required".to_string())
        );
    }

    #[test]
    fn handle_redirect_errors_on_a_connection_closed_before_any_request_line() {
        // A client that connects and disappears without ever sending a
        // request line (EOF on the very first byte read) must be reported
        // as an error rather than panicking — `read_request_line` seeing
        // `Ok(0)` on its very first read is exactly this case.
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let port = listener.local_addr().unwrap().port();

        let client = TcpStream::connect(("127.0.0.1", port)).unwrap();
        drop(client); // closes before writing anything

        let (stream, _addr) = listener.accept().unwrap();
        let result = handle_redirect(stream, "expected-state");
        assert!(result.is_err());
    }

    #[test]
    fn read_request_line_times_out_on_a_stalled_partial_line() {
        // A client that sends a partial request line (no trailing `\n`) and
        // then simply stops — without closing the connection — must not
        // hang past the overall deadline. A per-`read()` timeout alone
        // wouldn't catch this if it were reset to a fresh window on every
        // successful read; `read_request_line`'s `deadline` parameter must
        // still expire the read once the total budget runs out, regardless
        // of how many individual bytes trickled in before then.
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let port = listener.local_addr().unwrap().port();

        let mut client = TcpStream::connect(("127.0.0.1", port)).unwrap();
        client.write_all(b"GET /?code=AB").unwrap(); // no newline; stays open

        let (stream, _addr) = listener.accept().unwrap();
        let start = Instant::now();
        let result = read_request_line(
            &stream,
            SIGNIN_REQUEST_LINE_MAX,
            Instant::now() + Duration::from_millis(200),
        );
        assert!(result.is_err(), "expected a timeout error, got {result:?}");
        assert!(
            start.elapsed() < Duration::from_secs(2),
            "read_request_line did not respect its deadline: took {:?}",
            start.elapsed()
        );

        drop(client); // keep the connection alive until the assertions above run
    }

    #[test]
    fn read_request_line_errors_when_the_size_limit_is_exceeded() {
        // A connection that keeps sending bytes with no `\n` must be capped
        // by `max_bytes`, not just by the deadline — otherwise a fast,
        // never-terminating stream could grow the buffer unboundedly for as
        // long as the deadline allows.
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let port = listener.local_addr().unwrap().port();

        let mut client = TcpStream::connect(("127.0.0.1", port)).unwrap();
        client.write_all(&[b'a'; 20]).unwrap(); // no newline

        let (stream, _addr) = listener.accept().unwrap();
        // A generous deadline, so the size cap (not the deadline) is what's
        // actually under test here.
        let result = read_request_line(&stream, 10, Instant::now() + Duration::from_secs(5));
        assert!(result.is_err());

        drop(client);
    }

    /// Sends `SignIn` and plays the browser: lands on the `redirect_uri` of
    /// `SignInStarted` with a code and its `state`. Returns that
    /// `redirect_uri` and the loopback listener's response.
    fn sign_in_through_loopback(handle: &SyncHandle) -> (String, String) {
        sign_in_through_loopback_with(handle, |state| format!("code=THECODE&state={state}"))
    }

    /// [`sign_in_through_loopback`] landing on `/?<query(state)>`.
    fn sign_in_through_loopback_with(
        handle: &SyncHandle,
        redirect_query: impl Fn(&str) -> String,
    ) -> (String, String) {
        handle.cmd_tx.send(SyncCommand::SignIn).unwrap();
        let events = wait_for(&handle.evt_rx, |e| {
            matches!(e, SyncEvent::SignInStarted { .. })
        });
        let authorize_url = events
            .iter()
            .find_map(|e| match e {
                SyncEvent::SignInStarted { authorize_url } => Some(authorize_url.clone()),
                _ => None,
            })
            .expect("SignInStarted carries the authorize_url");
        let query = authorize_url.split_once('?').map(|(_, q)| q).unwrap_or("");
        let params = parse_query(query);
        let param = |name: &str| {
            params
                .iter()
                .find(|(k, _)| k == name)
                .map(|(_, v)| v.clone())
                .unwrap_or_else(|| panic!("authorize_url carries {name}"))
        };
        let (redirect_uri, state) = (param("redirect_uri"), param("state"));
        let port: u16 = redirect_uri
            .rsplit(':')
            .next()
            .and_then(|p| p.parse().ok())
            .expect("redirect_uri ends with the loopback port");
        let mut client = TcpStream::connect(("127.0.0.1", port)).expect("connect to loopback");
        let request = format!(
            "GET /?{} HTTP/1.1\r\nHost: localhost\r\n\r\n",
            redirect_query(&state)
        );
        client.write_all(request.as_bytes()).unwrap();
        let mut response = String::new();
        client.read_to_string(&mut response).unwrap();
        (redirect_uri, response)
    }

    #[test]
    fn sign_in_completes_via_loopback_redirect_and_caches_token() {
        // End-to-end proof of the port/redirect wiring: `begin_auth` must be
        // called with the SAME port `listen_for_code` accepts on, or this
        // "browser" (a raw TcpStream) would have nowhere to connect to.
        let routes = vec![
            Route {
                method: "POST".into(),
                path_prefix: "/organizations/oauth2/v2.0/token".into(),
                status: 200,
                headers: vec![],
                body: r#"{"access_token":"AT","refresh_token":"RT","expires_in":3600}"#.into(),
            },
            Route {
                method: "GET".into(),
                path_prefix: "/me/mailFolders".into(),
                status: 200,
                headers: vec![],
                body: r#"{"value":[]}"#.into(),
            },
        ];
        let srv = FakeServer::start(routes);
        let base = srv.base_url.clone();

        let dir = unique_dir("signin-loopback");
        let store_path = dir.join("mail.db");
        let token_path = dir.join("token.bin"); // no seed_token: starts signed out

        let handle = spawn_with_bases(
            store_path,
            token_path.clone(),
            test_cfg(),
            3650,
            base.clone(),
            base,
            Duration::from_secs(3600),
        );

        wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::SignInRequired));

        let (redirect_uri, response) = sign_in_through_loopback(&handle);
        // Entra matches the loopback redirect host literally and the Graph CLI
        // client registers `http://localhost` (not `http://127.0.0.1`), so the
        // redirect we send MUST use the `localhost` host or sign-in fails with
        // AADSTS50011.
        assert!(
            redirect_uri.starts_with("http://localhost:"),
            "redirect_uri must use the localhost host, got {redirect_uri}"
        );
        assert!(response.starts_with("HTTP/1.1 200"));
        assert!(response.to_lowercase().contains("close this tab"));

        // The redeem + cache-save + resync path then runs to completion.
        wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::FoldersUpdated));
        let cached = tokencache::load(&token_path)
            .unwrap()
            .expect("token cached after sign-in");
        assert_eq!(cached.access_token, "AT");

        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn sign_in_reenters_signin_required_when_the_redirect_state_mismatches() {
        // A redirect whose `state` doesn't match must be rejected rather
        // than redeemed — otherwise the loopback listener would accept a
        // code from anyone who can hit 127.0.0.1 during the sign-in window.
        let srv = FakeServer::start(vec![Route {
            method: "POST".into(),
            path_prefix: "/organizations/oauth2/v2.0/token".into(),
            status: 200,
            headers: vec![],
            body: r#"{"access_token":"AT","refresh_token":"RT","expires_in":3600}"#.into(),
        }]);
        let base = srv.base_url.clone();

        let dir = unique_dir("signin-state-mismatch");
        let store_path = dir.join("mail.db");
        let token_path = dir.join("token.bin");

        let handle = spawn_with_bases(
            store_path,
            token_path.clone(),
            test_cfg(),
            3650,
            base.clone(),
            base,
            Duration::from_secs(3600),
        );

        wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::SignInRequired));
        handle.cmd_tx.send(SyncCommand::SignIn).unwrap();

        let events = wait_for(&handle.evt_rx, |e| {
            matches!(e, SyncEvent::SignInStarted { .. })
        });
        let authorize_url = events
            .iter()
            .find_map(|e| match e {
                SyncEvent::SignInStarted { authorize_url } => Some(authorize_url.clone()),
                _ => None,
            })
            .unwrap();
        let query = authorize_url.split_once('?').map(|(_, q)| q).unwrap_or("");
        let redirect_uri = parse_query(query)
            .into_iter()
            .find(|(k, _)| k == "redirect_uri")
            .map(|(_, v)| v)
            .unwrap();
        let port: u16 = redirect_uri.rsplit(':').next().unwrap().parse().unwrap();

        let mut client = TcpStream::connect(("127.0.0.1", port)).unwrap();
        client
            .write_all(b"GET /?code=THECODE&state=wrong-state HTTP/1.1\r\nHost: localhost\r\n\r\n")
            .unwrap();
        let mut response = String::new();
        client.read_to_string(&mut response).unwrap();
        assert!(response.starts_with("HTTP/1.1 200"));
        assert!(response.to_lowercase().contains("failed"));

        // No token was ever cached, and the engine falls back to
        // sign-in-required rather than getting stuck.
        wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::SignInRequired));
        assert!(tokencache::load(&token_path).unwrap().is_none());

        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn calendar_window_defaults_to_30_days_back_and_180_days_forward() {
        // 2026-07-18T13:37:05Z, a fixed base in the middle of a day, so this
        // doesn't depend on the wall clock — the whole point of
        // `calendar_window` taking `base` as a parameter rather than reading
        // `SystemTime::now()` itself. The window starts at the day.
        let base = UNIX_EPOCH + Duration::from_secs(1_784_332_800 + 13 * 3600 + 37 * 60 + 5);
        let (from, to) = calendar_window(base, CalendarWindow::default());
        assert_eq!(from, "2026-06-18T00:00:00Z");
        // The whole of the 180th day: 181 days after the start of today.
        assert_eq!(to, "2027-01-15T00:00:00Z");
        // Every instant of the day gives the same bounds, so a deltaLink
        // over them holds all day.
        let midnight = UNIX_EPOCH + Duration::from_secs(1_784_332_800);
        let last_second = UNIX_EPOCH + Duration::from_secs(1_784_332_800 + 86_399);
        for t in [midnight, last_second] {
            assert_eq!(
                calendar_window(t, CalendarWindow::default()),
                (from.clone(), to.clone())
            );
        }
        let custom = CalendarWindow {
            past_days: 3,
            future_days: 10,
        };
        assert_eq!(
            calendar_window(base, custom),
            (
                "2026-07-15T00:00:00Z".to_string(),
                "2026-07-29T00:00:00Z".to_string()
            )
        );
    }

    /// A Graph calendar-event JSON body shaped like `Event::from_json`
    /// expects — same shape `graph::client`'s own `sample_event_json` test
    /// fixture uses, duplicated here since that one is private to that module.
    fn calendar_event_json(id: &str, start: &str, end: &str) -> String {
        format!(
            r#"{{"id":"{id}","subject":"Standup",
            "start":{{"dateTime":"{start}.0000000","timeZone":"UTC"}},
            "end":{{"dateTime":"{end}.0000000","timeZone":"UTC"}},
            "isAllDay":false,
            "location":{{"displayName":"Room"}},
            "organizer":{{"emailAddress":{{"name":"Org","address":"org@x"}}}},
            "responseStatus":{{"response":"none"}},
            "seriesMasterId":null,
            "bodyPreview":"p","webLink":"https://x/{id}",
            "lastModifiedDateTime":"2026-07-17T00:00:00Z",
            "body":{{"contentType":"html","content":"agenda"}},
            "attendees":[{{"type":"required","status":{{"response":"none"}},"emailAddress":{{"name":"Bob","address":"bob@x"}}}}]
            }}"#
        )
    }

    // --- Every calendar (#1984) ---

    /// One `/me/calendars` item.
    fn calendar_json(id: &str, default: bool, owner: &str) -> String {
        format!(
            r##"{{"id":"{id}","name":"n{id}","color":"lightBlue","hexColor":"#3366ff",
            "isDefaultCalendar":{default},"canEdit":true,
            "owner":{{"name":"Owner","address":"{owner}"}}}}"##
        )
    }

    /// A `value` page of events.
    fn events_body(events: &[String]) -> String {
        format!(r#"{{"value":[{}]}}"#, events.join(","))
    }

    /// `body` (a `value` page) as the last page of a calendar delta round,
    /// ending with deltaLink `link` (#2013).
    fn with_delta_link(body: &str, link: &str) -> String {
        let open = body.trim_end().strip_suffix('}').expect("a JSON object");
        format!(r#"{open},"@odata.deltaLink":"{link}"}}"#)
    }

    /// The deltaLink `calendar_routes` ends `id`'s rounds with: a relative
    /// path, which `full_url` joins to the fake server's base.
    fn delta_link_of(id: &str) -> String {
        format!("/cal-delta/{id}?token=1")
    }

    /// The routes a calendar refresh asks for (#1984, #2013): for each of
    /// `views` (`status`, `body`; a 429 carries `Retry-After: 30`), the
    /// calendar's initial `calendarView/delta` round (`body`, with
    /// `delta_link_of` added when it is a 200), a round from that link
    /// with no change, and the plain `calendarView` a `FetchCalendarRange`
    /// asks for (`body` as is); then the `/me/calendars` list of `cals`
    /// (id, default, owner). The list's prefix ends in `?`, so it never
    /// answers a view, and the view prefixes end in `?`, so none answers
    /// another: the fake server takes the first route whose prefix
    /// matches.
    fn calendar_routes(cals: &[(&str, bool, &str)], views: Vec<(&str, u16, String)>) -> Vec<Route> {
        let route = |path_prefix: String, status: u16, body: String| Route {
            method: "GET".into(),
            path_prefix,
            status,
            headers: if status == 429 {
                vec![("Retry-After".into(), "30".into())]
            } else {
                vec![]
            },
            body,
        };
        let mut routes = Vec::new();
        for (id, status, body) in views {
            let link = delta_link_of(id);
            let (delta, unchanged) = if status == 200 {
                (
                    with_delta_link(&body, &link),
                    with_delta_link(r#"{"value":[]}"#, &link),
                )
            } else {
                (body.clone(), body.clone())
            };
            routes.push(route(
                format!("/me/calendars/{id}/calendarView/delta?"),
                status,
                delta,
            ));
            routes.push(route(link, status, unchanged));
            routes.push(route(
                format!("/me/calendars/{id}/calendarView?"),
                status,
                body,
            ));
        }
        let items: Vec<String> = cals
            .iter()
            .map(|(id, default, owner)| calendar_json(id, *default, owner))
            .collect();
        routes.push(get_route("/me/calendars?", 200, &events_body(&items)));
        routes
    }

    /// An event `calendar_event_json` shapes, starting `from_now` seconds
    /// from now for half an hour: inside `calendar_window(now)`.
    fn event_from_now(id: &str, from_now: u64) -> String {
        let start = now_unix() + from_now;
        calendar_event_json(
            id,
            unix_to_iso8601(start).trim_end_matches('Z'),
            unix_to_iso8601(start + 1800).trim_end_matches('Z'),
        )
    }

    /// A stored event of `calendar` starting `from_now` seconds from now
    /// (negative: in the past).
    fn stored_event(id: &str, calendar: &str, from_now: i64) -> NewEvent {
        let start = (now_unix() as i64 + from_now) as u64;
        NewEvent {
            id: id.into(),
            subject: id.into(),
            start_utc: unix_to_iso8601(start),
            end_utc: unix_to_iso8601(start + 1800),
            calendar_id: calendar.into(),
            ..Default::default()
        }
    }

    /// Starts an engine on `routes` (plus the mail backfill's) with `seed`
    /// run on its store first, and waits for the backfill to land.
    fn spawn_calendar_engine(
        tag: &str,
        routes: Vec<Route>,
        seed: impl FnOnce(&Store),
    ) -> (FakeServer, SyncHandle, PathBuf, PathBuf) {
        spawn_calendar_engine_with(tag, routes, seed, EngineOptions::without_prefetch())
    }

    /// [`spawn_calendar_engine`] with the engine's options.
    fn spawn_calendar_engine_with(
        tag: &str,
        routes: Vec<Route>,
        seed: impl FnOnce(&Store),
        options: EngineOptions,
    ) -> (FakeServer, SyncHandle, PathBuf, PathBuf) {
        let routes = routes.into_iter().map(|r| (r, None)).collect();
        spawn_calendar_engine_limited(tag, routes, seed, options)
    }

    /// [`spawn_calendar_engine_with`] on routes that may answer a limited
    /// number of requests (`FakeServer::start_limited`).
    fn spawn_calendar_engine_limited(
        tag: &str,
        routes: Vec<(Route, Option<usize>)>,
        seed: impl FnOnce(&Store),
        options: EngineOptions,
    ) -> (FakeServer, SyncHandle, PathBuf, PathBuf) {
        let routes = routes
            .into_iter()
            .map(|(r, left)| (r, left, Duration::ZERO))
            .collect();
        spawn_calendar_engine_paced(tag, routes, seed, options)
    }

    /// [`spawn_calendar_engine_limited`] on routes that may also wait
    /// before they answer (`FakeServer::start_paced`).
    fn spawn_calendar_engine_paced(
        tag: &str,
        routes: Vec<(Route, Option<usize>, Duration)>,
        seed: impl FnOnce(&Store),
        options: EngineOptions,
    ) -> (FakeServer, SyncHandle, PathBuf, PathBuf) {
        let mut routes = routes;
        routes.extend(
            backfill_routes()
                .into_iter()
                .map(|r| (r, None, Duration::ZERO)),
        );
        let srv = FakeServer::start_paced(routes);
        let base = srv.base_url.clone();
        let dir = unique_dir(tag);
        let store_path = dir.join("mail.db");
        let token_path = dir.join("token.bin");
        seed_token(&token_path);
        seed(&Store::open(&store_path).unwrap());
        let handle = spawn_with_bases_and_options(
            store_path.clone(),
            token_path,
            test_cfg(),
            3650,
            base.clone(),
            base,
            Duration::from_secs(3600),
            options,
        );
        wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::FoldersUpdated));
        (srv, handle, store_path, dir)
    }

    /// Waits for the `n`th `CalendarUpdated`, returning every event seen.
    fn wait_for_calendar_updates(rx: &Receiver<SyncEvent>, n: usize) -> Vec<SyncEvent> {
        let mut seen = 0;
        wait_for(rx, |e| {
            if matches!(e, SyncEvent::CalendarUpdated) {
                seen += 1;
            }
            seen == n
        })
    }

    fn ids_in(store: &Store, calendar: &str) -> Vec<String> {
        store
            .events_in_range(
                "2000-01-01T00:00:00Z",
                "2100-01-01T00:00:00Z",
                &[calendar.to_string()],
            )
            .unwrap()
            .into_iter()
            .map(|e| e.id)
            .collect()
    }

    /// How many of `calendar`'s views were requested from request `from`
    /// on: its `calendarView`, `calendarView/delta` and deltaLink rounds.
    fn view_requests(srv: &FakeServer, from: usize, calendar: &str) -> usize {
        let prefix = format!("/me/calendars/{calendar}/calendarView");
        let link = format!("/cal-delta/{calendar}?");
        paths_from(srv, from)
            .iter()
            .filter(|p| p.starts_with(&prefix) || p.starts_with(&link))
            .count()
    }

    #[test]
    fn created_event_in_a_second_calendar_stays_in_it_through_both_refreshes() {
        // #2048. Startup runs no calendar pass (only the tick does), so the
        // first refresh after the create is an initial round for each
        // calendar, whose view lists NEW1 in CAL-B only, and the second a
        // delta round each, CAL-B's naming NEW1 again with a new subject.
        let created = event_from_now("NEW1", 3600);
        let initial = created.replacen("Standup", "Adopted", 1);
        let delta = created.replacen("Standup", "Adopted again", 1);
        let mut routes = vec![
            Route {
                method: "POST".into(),
                path_prefix: "/me/calendars/CAL-B/events".into(),
                status: 201,
                headers: vec![],
                body: created,
            },
            get_route(
                &delta_link_of("CAL-B"),
                200,
                &with_delta_link(&events_body(&[delta]), &delta_link_of("CAL-B")),
            ),
        ];
        routes.extend(calendar_routes(
            &[("CAL-A", true, "me@x"), ("CAL-B", false, "me@x")],
            vec![
                ("CAL-A", 200, events_body(&[event_from_now("EA", 7200)])),
                ("CAL-B", 200, events_body(&[initial])),
            ],
        ));
        let start = now_unix() + 3600;
        let mut local_id = String::new();
        let (srv, handle, store_path, dir) =
            spawn_calendar_engine("calendar-create-in", routes, |s| {
                let cal = |id: &str, default: bool| crate::graph::model::Calendar {
                    id: id.into(),
                    is_default: default,
                    can_edit: true,
                    owner_addr: "me@x".into(),
                    ..Default::default()
                };
                s.replace_calendars(&[cal("CAL-A", true), cal("CAL-B", false)])
                    .unwrap();
                local_id = s
                    .create_local_event(
                        &crate::store::LocalEventFields {
                            subject: "Standup".into(),
                            start_utc: unix_to_iso8601(start),
                            end_utc: unix_to_iso8601(start + 1800),
                            calendar_id: Some("CAL-B".into()),
                            ..Default::default()
                        },
                        "Me",
                        "me@x",
                    )
                    .unwrap();
            });
        let subject_in_b = || {
            let rows = Store::open(&store_path)
                .unwrap()
                .events_in_range(
                    "2000-01-01T00:00:00Z",
                    "2100-01-01T00:00:00Z",
                    &["CAL-B".to_string()],
                )
                .unwrap();
            rows.into_iter()
                .map(|r| (r.id, r.subject))
                .collect::<Vec<_>>()
        };
        assert_eq!(subject_in_b(), [(local_id.clone(), "Standup".to_string())]);
        handle
            .cmd_tx
            .send(SyncCommand::CreateEvent {
                id: local_id.clone(),
            })
            .unwrap();
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        // One `CalendarUpdated` for the create, one for the refresh.
        let seen = wait_for_calendar_updates(&handle.evt_rx, 2);
        assert!(
            !seen.iter().any(|e| matches!(e, SyncEvent::Error(_))),
            "{seen:?}"
        );
        let initial_end = srv.requests().len();
        assert_eq!(
            subject_in_b(),
            [("NEW1".to_string(), "Adopted".to_string())]
        );
        assert_eq!(ids_in(&Store::open(&store_path).unwrap(), "CAL-A"), ["EA"]);
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);

        let reqs = srv.requests();
        let paths: Vec<&str> = reqs.iter().map(|r| r.path.as_str()).collect();
        let post = reqs
            .iter()
            .position(|r| r.method == "POST")
            .expect("the create was sent");
        assert_eq!(reqs[post].path, "/me/calendars/CAL-B/events");
        assert_eq!(reqs.iter().filter(|r| r.method == "POST").count(), 1);
        for cal in ["CAL-A", "CAL-B"] {
            // The first refresh: an initial round, after the create.
            let initial = format!("/me/calendars/{cal}/calendarView/delta?");
            assert!(
                paths[post..initial_end]
                    .iter()
                    .any(|p| p.starts_with(&initial)),
                "no initial {cal} round after the create: {paths:?}"
            );
            // The second: a delta round.
            assert!(
                paths[initial_end..].contains(&delta_link_of(cal).as_str()),
                "no {cal} delta round: {paths:?}"
            );
        }
        assert_eq!(
            subject_in_b(),
            [("NEW1".to_string(), "Adopted again".to_string())]
        );
        let store = Store::open(&store_path).unwrap();
        assert_eq!(ids_in(&store, "CAL-A"), ["EA"]);
        assert!(store.event_for_send(&local_id).unwrap().is_none());
        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn refresh_calendar_syncs_two_calendars_into_separate_ids() {
        // B's event names another calendar in its JSON: the URL decides.
        let b_event = event_from_now("EB", 7200).replacen(
            r#""isAllDay":false"#,
            r#""isAllDay":false,"calendar":{"id":"WRONG"}"#,
            1,
        );
        assert!(b_event.contains("WRONG"));
        let routes = calendar_routes(
            &[("CAL-A", true, "me@x"), ("CAL-B", false, "ME@X")],
            vec![
                ("CAL-A", 200, events_body(&[event_from_now("EA", 3600)])),
                ("CAL-B", 200, events_body(&[b_event])),
            ],
        );
        let (_srv, handle, store_path, dir) = spawn_calendar_engine("calendar-two", routes, |_| {});
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        let seen = wait_for_calendar_updates(&handle.evt_rx, 1);
        assert!(seen.contains(&SyncEvent::CalendarsUpdated), "{seen:?}");
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);

        let store = Store::open(&store_path).unwrap();
        assert_eq!(ids_in(&store, "CAL-A"), ["EA"]);
        assert_eq!(ids_in(&store, "CAL-B"), ["EB"]);
        assert!(ids_in(&store, "WRONG").is_empty());
        let cals = store.calendars().unwrap();
        assert_eq!(cals.len(), 2);
        let a = &cals[0];
        assert_eq!(a.calendar.id, "CAL-A");
        assert_eq!(a.calendar.name, "nCAL-A");
        assert_eq!(a.calendar.color, "lightBlue");
        assert_eq!(a.calendar.hex_color, "#3366ff");
        assert!(a.calendar.is_default && a.calendar.can_edit);
        assert_eq!(a.calendar.owner_addr, "me@x");
        assert!(!cals[1].calendar.is_default);
        assert!(cals.iter().all(|c| c.syncs), "same owner, either case");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn set_calendars_drops_a_calendars_events_and_stops_syncing_it() {
        let routes = calendar_routes(
            &[("CAL-A", true, "me@x"), ("CAL-B", false, "me@x")],
            vec![
                ("CAL-A", 200, events_body(&[event_from_now("EA", 3600)])),
                ("CAL-B", 200, events_body(&[event_from_now("EB", 7200)])),
            ],
        );
        let (srv, handle, store_path, dir) = spawn_calendar_engine("calendar-set", routes, |_| {});
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        assert_eq!(ids_in(&Store::open(&store_path).unwrap(), "CAL-B"), ["EB"]);

        // Only A: B's events go, and the refresh that follows skips B.
        let before = srv.requests().len();
        handle
            .cmd_tx
            .send(SyncCommand::SetCalendars {
                ids: Some(vec!["CAL-A".into()]),
            })
            .unwrap();
        let seen = wait_for_calendar_updates(&handle.evt_rx, 2);
        assert!(seen.contains(&SyncEvent::CalendarsUpdated), "{seen:?}");
        let store = Store::open(&store_path).unwrap();
        assert_eq!(ids_in(&store, "CAL-A"), ["EA"]);
        assert!(ids_in(&store, "CAL-B").is_empty());
        let syncs: Vec<bool> = store.calendars().unwrap().iter().map(|c| c.syncs).collect();
        assert_eq!(syncs, [true, false]);
        assert_eq!(view_requests(&srv, before, "CAL-A"), 1);
        assert_eq!(view_requests(&srv, before, "CAL-B"), 0);

        // A later refresh still skips B.
        let before = srv.requests().len();
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        assert_eq!(view_requests(&srv, before, "CAL-B"), 0);
        assert!(ids_in(&Store::open(&store_path).unwrap(), "CAL-B").is_empty());

        // Back to the default: B syncs again.
        let before = srv.requests().len();
        handle
            .cmd_tx
            .send(SyncCommand::SetCalendars { ids: None })
            .unwrap();
        let seen = wait_for_calendar_updates(&handle.evt_rx, 2);
        assert!(seen.contains(&SyncEvent::CalendarsUpdated), "{seen:?}");
        assert_eq!(view_requests(&srv, before, "CAL-B"), 1);
        assert_eq!(ids_in(&Store::open(&store_path).unwrap(), "CAL-B"), ["EB"]);

        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn refresh_calendar_skips_calendars_of_other_owners_by_default() {
        let routes = calendar_routes(
            &[("CAL-A", true, "me@x"), ("SHARED", false, "boss@x")],
            vec![
                ("CAL-A", 200, events_body(&[event_from_now("EA", 3600)])),
                ("SHARED", 200, events_body(&[event_from_now("ES", 3600)])),
            ],
        );
        let (srv, handle, store_path, dir) =
            spawn_calendar_engine("calendar-shared", routes, |_| {});
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);

        let store = Store::open(&store_path).unwrap();
        let cals = store.calendars().unwrap();
        assert_eq!(cals[1].calendar.id, "SHARED");
        assert!(cals[0].syncs && !cals[1].syncs);
        assert_eq!(view_requests(&srv, 0, "SHARED"), 0);
        assert_eq!(ids_in(&store, "CAL-A"), ["EA"]);
        assert!(ids_in(&store, "SHARED").is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn refresh_calendar_keeps_a_calendars_events_when_its_view_fails() {
        let routes = calendar_routes(
            &[("CAL-A", true, "me@x"), ("CAL-B", false, "me@x")],
            vec![
                ("CAL-A", 200, events_body(&[event_from_now("EA", 3600)])),
                (
                    "CAL-B",
                    404,
                    r#"{"error":{"code":"ErrorItemNotFound"}}"#.into(),
                ),
            ],
        );
        let (_srv, handle, store_path, dir) =
            spawn_calendar_engine("calendar-view-fails", routes, |s| {
                s.upsert_event(&stored_event("A-OLD", "CAL-A", 86400))
                    .unwrap();
                s.upsert_event(&stored_event("B-KEPT", "CAL-B", 86400))
                    .unwrap();
            });
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        let seen = wait_for_calendar_updates(&handle.evt_rx, 1);
        assert!(
            seen.iter().any(|e| matches!(e, SyncEvent::Error(_))),
            "{seen:?}"
        );
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);

        let store = Store::open(&store_path).unwrap();
        assert_eq!(ids_in(&store, "CAL-A"), ["EA"], "A's window was replaced");
        assert_eq!(ids_in(&store, "CAL-B"), ["B-KEPT"]);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn refresh_calendar_writes_nothing_when_a_view_is_throttled() {
        let routes = calendar_routes(
            &[("CAL-A", true, "me@x"), ("CAL-B", false, "me@x")],
            vec![
                ("CAL-A", 200, events_body(&[event_from_now("EA", 3600)])),
                ("CAL-B", 429, "{}".into()),
            ],
        );
        let (srv, handle, store_path, dir) =
            spawn_calendar_engine("calendar-throttled", routes, |s| {
                s.upsert_event(&stored_event("A-OLD", "", 86400)).unwrap();
            });
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        // Commands run in order, so this one's `CalendarUpdated` comes after
        // the throttled pass ended; inside the `Retry-After` wait it
        // refreshes nothing.
        handle
            .cmd_tx
            .send(SyncCommand::SetCalendars { ids: None })
            .unwrap();
        let seen = wait_for_calendar_updates(&handle.evt_rx, 1);
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);
        assert_eq!(view_requests(&srv, 0, "CAL-B"), 1, "{seen:?}");
        assert_eq!(view_requests(&srv, 0, "CAL-A"), 1);

        let store = Store::open(&store_path).unwrap();
        // The list was stored; no event of the pass was, and the old row
        // was neither adopted nor replaced.
        assert_eq!(store.calendars().unwrap().len(), 2);
        assert!(ids_in(&store, "CAL-A").is_empty());
        assert_eq!(ids_in(&store, ""), ["A-OLD"]);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn refresh_calendar_adopts_pre_1984_rows_into_the_default_calendar() {
        let routes = calendar_routes(
            &[("CAL-A", true, "me@x")],
            vec![("CAL-A", 200, events_body(&[event_from_now("E1", 86400)]))],
        );
        let mut local = String::new();
        let (_srv, handle, store_path, dir) =
            spawn_calendar_engine("calendar-adopt", routes, |s| {
                // Stored before #1984: no calendar id.
                s.upsert_event(&stored_event("E1", "", 86400)).unwrap();
                s.upsert_event(&stored_event("HISTORY", "", -60 * 86400))
                    .unwrap();
                local = s
                    .create_local_event(
                        &crate::store::LocalEventFields {
                            subject: "Local".into(),
                            start_utc: unix_to_iso8601(now_unix() + 3 * 86400),
                            end_utc: unix_to_iso8601(now_unix() + 3 * 86400 + 1800),
                            ..Default::default()
                        },
                        "Me",
                        "me@x",
                    )
                    .unwrap();
            });
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);

        let store = Store::open(&store_path).unwrap();
        let mut ids = ids_in(&store, "CAL-A");
        ids.sort();
        let mut want = vec!["E1".to_string(), "HISTORY".to_string(), local];
        want.sort();
        assert_eq!(ids, want, "adopted once each, none deleted");
        assert!(ids_in(&store, "").is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }

    // --- calendarView delta over the kept window (#2013) ---
    //
    // A test that runs two passes and asserts the second used the stored
    // link would see an initial round instead if the passes straddled
    // 00:00 UTC (the window moves with the day). That window is a few
    // milliseconds a day, so there is no clock seam.

    /// Today's default window, as a pass computes it.
    fn today_window() -> (String, String) {
        calendar_window(SystemTime::now(), CalendarWindow::default())
    }

    /// The initial delta round's path of `calendar` over `[from, to)`.
    fn initial_delta_path(calendar: &str, from: &str, to: &str) -> String {
        format!("/me/calendars/{calendar}/calendarView/delta?startDateTime={from}&endDateTime={to}")
    }

    /// Every view request of `calendar` (`view_requests`' set), in order.
    fn view_paths(srv: &FakeServer, calendar: &str) -> Vec<String> {
        let prefix = format!("/me/calendars/{calendar}/calendarView");
        let link = format!("/cal-delta/{calendar}?");
        paths_from(srv, 0)
            .into_iter()
            .filter(|p| p.starts_with(&prefix) || p.starts_with(&link))
            .collect()
    }

    /// A calendar delta page of `items` ending with deltaLink `link`.
    fn calendar_delta_page(items: &[String], link: &str) -> String {
        with_delta_link(&events_body(items), link)
    }

    /// A delta page's `@removed` item.
    fn removed_json(id: &str) -> String {
        format!(r#"{{"id":"{id}","@removed":{{"reason":"deleted"}}}}"#)
    }

    /// Seeds `store` as if a pass over `[from, to)` had synced `calendar`
    /// (the default, owned by me@x) with `events`, ending with `link`.
    fn seed_synced_calendar(
        store: &Store,
        calendar: &str,
        events: Vec<NewEvent>,
        (from, to): (&str, &str),
        link: &str,
    ) {
        store
            .replace_calendars(&[crate::graph::model::Calendar {
                id: calendar.into(),
                is_default: true,
                owner_addr: "me@x".into(),
                ..Default::default()
            }])
            .unwrap();
        let fetched = FetchedCalendar {
            calendar_id: calendar.into(),
            attendees: events.iter().map(|e| (e.id.clone(), Vec::new())).collect(),
            events,
        };
        store
            .apply_calendar_sync(
                from,
                to,
                &[SyncedCalendar {
                    fetched,
                    round: CalendarRound::Window,
                    delta_link: link.into(),
                }],
                RangeStamp {
                    at: 1,
                    fresh_since: 0,
                },
            )
            .unwrap();
    }

    #[test]
    fn refresh_calendar_first_pass_is_an_initial_delta_over_the_window() {
        let routes = calendar_routes(
            &[("CAL-A", true, "me@x")],
            vec![("CAL-A", 200, events_body(&[event_from_now("EA", 3600)]))],
        );
        let (srv, handle, store_path, dir) =
            spawn_calendar_engine("calendar-delta-first", routes, |_| {});
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);

        let (from, to) = today_window();
        assert_eq!(
            view_paths(&srv, "CAL-A"),
            [initial_delta_path("CAL-A", &from, &to)]
        );
        let store = Store::open(&store_path).unwrap();
        assert_eq!(ids_in(&store, "CAL-A"), ["EA"]);
        assert_eq!(
            store.calendar_delta("CAL-A").unwrap(),
            Some(crate::store::CalendarDeltaState {
                from_utc: from,
                to_utc: to,
                delta_link: delta_link_of("CAL-A"),
            })
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn refresh_calendar_uses_the_custom_window_option() {
        let routes = calendar_routes(
            &[("CAL-A", true, "me@x")],
            vec![("CAL-A", 200, events_body(&[]))],
        );
        let window = CalendarWindow {
            past_days: 2,
            future_days: 5,
        };
        let options = EngineOptions {
            calendar_window: window,
            ..EngineOptions::without_prefetch()
        };
        let (srv, handle, store_path, dir) =
            spawn_calendar_engine_with("calendar-delta-custom", routes, |_| {}, options);
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);

        let (from, to) = calendar_window(SystemTime::now(), window);
        assert_ne!((from.clone(), to.clone()), today_window());
        assert_eq!(
            view_paths(&srv, "CAL-A"),
            [initial_delta_path("CAL-A", &from, &to)]
        );
        let state = Store::open(&store_path)
            .unwrap()
            .calendar_delta("CAL-A")
            .unwrap()
            .unwrap();
        assert_eq!((state.from_utc, state.to_utc), (from, to));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn calendar_delta_adds_updates_and_removes_occurrences() {
        let start = now_unix() + 3 * 3600;
        let moved = calendar_event_json(
            "E-CHANGE",
            unix_to_iso8601(start).trim_end_matches('Z'),
            unix_to_iso8601(start + 1800).trim_end_matches('Z'),
        )
        .replacen(r#""subject":"Standup""#, r#""subject":"Moved""#, 1);
        let routes = vec![
            get_route(
                "/me/calendars/CAL-A/calendarView/delta?",
                200,
                &calendar_delta_page(
                    &[
                        event_from_now("E-KEEP", 3600),
                        event_from_now("E-CHANGE", 7200),
                        event_from_now("E-GONE", 7200),
                    ],
                    "/cal-delta/CAL-A?token=1",
                ),
            ),
            get_route(
                "/cal-delta/CAL-A?token=1",
                200,
                &calendar_delta_page(
                    &[event_from_now("E-NEW", 5400), moved, removed_json("E-GONE")],
                    "/cal-delta/CAL-A?token=2",
                ),
            ),
            get_route(
                "/me/calendars?",
                200,
                &events_body(&[calendar_json("CAL-A", true, "me@x")]),
            ),
        ];
        let (srv, handle, store_path, dir) =
            spawn_calendar_engine("calendar-delta-changes", routes, |_| {});
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 2);
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);

        let (from, to) = today_window();
        assert_eq!(
            view_paths(&srv, "CAL-A"),
            [
                initial_delta_path("CAL-A", &from, &to),
                "/cal-delta/CAL-A?token=1".to_string()
            ],
            "the second pass runs the stored link"
        );
        let store = Store::open(&store_path).unwrap();
        let mut ids = ids_in(&store, "CAL-A");
        ids.sort();
        assert_eq!(ids, ["E-CHANGE", "E-KEEP", "E-NEW"]);
        let rows = store
            .events_in_range(&from, &to, &["CAL-A".to_string()])
            .unwrap();
        let row = |id: &str| rows.iter().find(|r| r.id == id).unwrap();
        assert_eq!(row("E-CHANGE").subject, "Moved");
        assert_eq!(row("E-CHANGE").start_utc, unix_to_iso8601(start));
        assert_eq!(row("E-KEEP").subject, "Standup", "not named: untouched");
        // A link-round event is stored under the calendar it was fetched for.
        assert_eq!(store.event_attendees("E-NEW").unwrap().len(), 1);
        assert_eq!(
            store.calendar_delta("CAL-A").unwrap().unwrap().delta_link,
            "/cal-delta/CAL-A?token=2"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn calendar_delta_removed_series_master_removes_its_occurrences() {
        let occurrence = |id: &str, from_now: u64| {
            event_from_now(id, from_now).replacen(
                r#""seriesMasterId":null"#,
                r#""seriesMasterId":"MASTER""#,
                1,
            )
        };
        let initial = "/me/calendars/CAL-A/calendarView/delta?";
        let routes = vec![
            (
                get_route(
                    initial,
                    200,
                    &calendar_delta_page(
                        &[
                            occurrence("O1", 3600),
                            occurrence("O2", 86400 + 3600),
                            event_from_now("SINGLE", 7200),
                        ],
                        "/cal-delta/CAL-A?token=1",
                    ),
                ),
                Some(1),
            ),
            // The series is gone at Graph by the next initial round.
            (
                get_route(
                    initial,
                    200,
                    &calendar_delta_page(
                        &[event_from_now("SINGLE", 7200)],
                        "/cal-delta/CAL-A?token=3",
                    ),
                ),
                None,
            ),
            (
                get_route(
                    "/cal-delta/CAL-A?token=1",
                    200,
                    &calendar_delta_page(&[removed_json("MASTER")], "/cal-delta/CAL-A?token=2"),
                ),
                None,
            ),
            (
                get_route(
                    "/me/calendars?",
                    200,
                    &events_body(&[calendar_json("CAL-A", true, "me@x")]),
                ),
                None,
            ),
        ];
        let (srv, handle, store_path, dir) = spawn_calendar_engine_limited(
            "calendar-delta-series",
            routes,
            |_| {},
            EngineOptions::without_prefetch(),
        );
        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        let mut ids = ids_in(&Store::open(&store_path).unwrap(), "CAL-A");
        ids.sort();
        assert_eq!(ids, ["O1", "O2", "SINGLE"]);

        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        let store = Store::open(&store_path).unwrap();
        assert_eq!(ids_in(&store, "CAL-A"), ["SINGLE"]);
        // The cascade drops the delta state: the master may only have
        // changed, so the next pass checks with an initial round.
        assert_eq!(store.calendar_delta("CAL-A").unwrap(), None);

        handle.cmd_tx.send(SyncCommand::RefreshCalendar).unwrap();
        wait_for_calendar_updates(&handle.evt_rx, 1);
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);
        let (from, to) = today_window();
        let initial_path = initial_delta_path("CAL-A", &from, &to);
        assert_eq!(
            view_paths(&srv, "CAL-A"),
            [
                initial_path.clone(),
                "/cal-delta/CAL-A?token=1".to_string(),
                initial_path
            ]
        );
        assert_eq!(ids_in(&store, "CAL-A"), ["SINGLE"]);
        assert_eq!(
            store.calendar_delta("CAL-A").unwrap().unwrap().delta_link,
            "/cal-delta/CAL-A?token=3"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

