    #[test]
    fn delete_event_quarantine_restores_the_event() {
        // The DELETE always 403s, so the optimistic local delete never
        // reached Graph. Every pass before the quarantine runs the stored
        // link, which (Graph's event unchanged) never names the event: only
        // the initial round the quarantine forces brings it back.
        let (from, to) = today_window();
        let mut routes = calendar_routes(
            &[("CAL-A", true, "me@x")],
            vec![("CAL-A", 200, events_body(&[event_from_now("E1", 3600)]))],
        );
        routes.insert(
            0,
            Route {
                method: "DELETE".into(),
                path_prefix: "/me/events/E1".into(),
                status: 403,
                headers: vec![],
                body: r#"{"error":{"code":"ErrorAccessDenied"}}"#.into(),
            },
        );
        let (srv, handle, store_path, dir) =
            spawn_calendar_engine("delete-event-reconverge", routes, |s| {
                seed_synced_calendar(
                    s,
                    "CAL-A",
                    vec![stored_event("E1", "CAL-A", 3600)],
                    (&from, &to),
                    &delta_link_of("CAL-A"),
                );
            });
        Store::open(&store_path)
            .unwrap()
            .delete_event("E1")
            .unwrap();
        handle
            .cmd_tx
            .send(SyncCommand::DeleteEvent { id: "E1".into() })
            .unwrap();
        for _ in 0..4 {
            handle.cmd_tx.send(SyncCommand::Refresh).unwrap();
        }
        wait_for(
            &handle.evt_rx,
            |e| matches!(e, SyncEvent::Error(m) if m.contains("quarantined")),
        );
        wait_for(&handle.evt_rx, |e| matches!(e, SyncEvent::CalendarUpdated));
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);

        let store = Store::open(&store_path).unwrap();
        assert_eq!(ids_in(&store, "CAL-A"), ["E1"], "the row is back");
        let views = view_paths(&srv, "CAL-A");
        assert!(
            views[..views.len() - 1]
                .iter()
                .all(|p| *p == delta_link_of("CAL-A")),
            "before the quarantine, link rounds only: {views:?}"
        );
        assert_eq!(
            views.last(),
            Some(&initial_delta_path("CAL-A", &from, &to)),
            "{views:?}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// #2113 (#1918 plan-spin): dropping to sign-in ends a back-off, so a
    /// signed-out engine whose throttle or offline deadline has passed
    /// waits for its tick instead of waking at once.
    #[test]
    fn plan_spin_signin_clears_a_passed_retry() {
        let (cmd_tx, cmd_rx) = mpsc::channel();
        let (evt_tx, evt_rx) = mpsc::channel();
        let config = EngineConfig {
            store_path: PathBuf::from("unused.db"),
            token_path: PathBuf::from("unused-token.json"),
            cfg: AuthConfig::default(),
            backfill_days: 30,
            graph_base: "http://127.0.0.1:9".into(),
            auth_base: "http://127.0.0.1:9".into(),
            tick: HOUR,
            options: EngineOptions::without_prefetch(),
        };
        let mut engine = Engine::new(config, Store::open_in_memory().unwrap(), cmd_rx, evt_tx);
        engine.next_tick = Instant::now() + HOUR;
        engine.next_retry = Some(Instant::now() - Duration::from_secs(1));
        engine.backoff = BACKOFF_MAX;
        assert_eq!(engine.recv_timeout(), Duration::ZERO, "the spin's cause");
        engine.enter_signin();
        assert!(engine.token.is_none());
        assert_eq!(engine.next_retry, None);
        assert_eq!(engine.backoff, BACKOFF_MIN);
        assert!(engine.recv_timeout() > Duration::ZERO);
        assert!(!engine.due(), "no wake is due");
        assert!(matches!(evt_rx.try_recv(), Ok(SyncEvent::SignInRequired)));
        drop(cmd_tx);
    }

    /// #2113 (#2038 plan-del404): a DELETE answered 404 (a retry after a
    /// lost 204, or an event removed elsewhere) is done: the op goes at the
    /// first answer, with no `Error`, no quarantine (no mail reconverge)
    /// and no calendar reset, and the row stays gone.
    #[test]
    fn plan_del404_delete_event_404_is_dropped_as_done() {
        let (from, to) = today_window();
        // The view holds E1, so a calendar reset's initial round would
        // bring the row back: none may run.
        let mut routes = calendar_routes(
            &[("CAL-A", true, "me@x")],
            vec![("CAL-A", 200, events_body(&[event_from_now("E1", 3600)]))],
        );
        routes.insert(
            0,
            Route {
                method: "DELETE".into(),
                path_prefix: "/me/events/E1".into(),
                status: 404,
                headers: vec![],
                body: r#"{"error":{"code":"ErrorItemNotFound"}}"#.into(),
            },
        );
        let (srv, handle, store_path, dir) =
            spawn_calendar_engine("delete-event-404", routes, |s| {
                seed_synced_calendar(
                    s,
                    "CAL-A",
                    vec![stored_event("E1", "CAL-A", 3600)],
                    (&from, &to),
                    &delta_link_of("CAL-A"),
                );
            });
        Store::open(&store_path)
            .unwrap()
            .delete_event("E1")
            .unwrap();
        handle
            .cmd_tx
            .send(SyncCommand::DeleteEvent { id: "E1".into() })
            .unwrap();
        // Commands run in order: this one's `Error` comes after the
        // delete's drain is done.
        fetch_range(&handle, "bad", "bad");
        let seen = wait_for(
            &handle.evt_rx,
            |e| matches!(e, SyncEvent::Error(m) if m.starts_with("fetch calendar range")),
        );
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);
        let errors: Vec<&String> = seen
            .iter()
            .filter_map(|e| match e {
                SyncEvent::Error(m) if !m.starts_with("fetch calendar range") => Some(m),
                _ => None,
            })
            .collect();
        assert!(errors.is_empty(), "{errors:?}");
        let store = Store::open(&store_path).unwrap();
        assert!(store.pending_ops().unwrap().is_empty(), "the op is done");
        assert!(!store.reconverge_pending().unwrap(), "no quarantine");
        let deletes = srv
            .requests()
            .iter()
            .filter(|r| r.method == "DELETE")
            .count();
        assert_eq!(deletes, 1, "not retried");
        assert!(
            view_paths(&srv, "CAL-A")
                .iter()
                .all(|p| *p == delta_link_of("CAL-A")),
            "no calendar reset: {:?}",
            view_paths(&srv, "CAL-A")
        );
        assert!(ids_in(&store, "CAL-A").is_empty(), "the row stays gone");
        let _ = std::fs::remove_dir_all(&dir);
    }

    // --- Calendar ranges on demand (#2014) ---

    /// A query parameter's value in a recorded request path.
    fn query_value(path: &str, key: &str) -> String {
        let query = path.split_once('?').map_or("", |(_, q)| q);
        query
            .split('&')
            .find_map(|kv| kv.strip_prefix(&format!("{key}=")))
            .unwrap_or_default()
            .to_string()
    }

    /// The `(startDateTime, endDateTime)` of each `calendarView` request of
    /// `calendar` from request `from` on.
    fn view_ranges(srv: &FakeServer, from: usize, calendar: &str) -> Vec<(String, String)> {
        let prefix = format!("/me/calendars/{calendar}/calendarView");
        paths_from(srv, from)
            .iter()
            .filter(|p| p.starts_with(&prefix))
            .map(|p| {
                (
                    query_value(p, "startDateTime"),
                    query_value(p, "endDateTime"),
                )
            })
            .collect()
    }

    /// How many calendar requests (the list, every view and deltaLink
    /// round) were made from request `from` on. The mail sync's own
    /// requests are not counted.
    fn calendar_requests(srv: &FakeServer, from: usize) -> usize {
        paths_from(srv, from)
            .iter()
            .filter(|p| p.starts_with("/me/calendars") || p.starts_with("/cal-delta/"))
            .count()
    }

    fn iso_from_now(days: i64) -> String {
        unix_to_iso8601((now_unix() as i64 + days * 86400) as u64)
    }

    fn fetch_range(handle: &SyncHandle, from: &str, to: &str) {
        handle
            .cmd_tx
            .send(SyncCommand::FetchCalendarRange {
                from_utc: from.into(),
                to_utc: to.into(),
            })
            .unwrap();
    }

    /// Waits for the `CalendarRangeFetched` of `[from, to)`.
    fn wait_for_range(rx: &Receiver<SyncEvent>, from: &str, to: &str) -> Vec<SyncEvent> {
        wait_for(
            rx,
            |e| matches!(e, SyncEvent::CalendarRangeFetched { from: f, to: t } if f == from && t == to),
        )
    }

    /// An event 200 days out: outside `calendar_window` (181 days).
    fn far_event(id: &str) -> String {
        let start = now_unix() + 200 * 86400;
        calendar_event_json(
            id,
            unix_to_iso8601(start).trim_end_matches('Z'),
            unix_to_iso8601(start + 1800).trim_end_matches('Z'),
        )
    }

    #[test]
    fn fetch_calendar_range_outside_the_window_is_fetched_once_then_served_from_the_store() {
        let routes = calendar_routes(
            &[("CAL-A", true, "me@x"), ("CAL-B", false, "me@x")],
            vec![
                ("CAL-A", 200, events_body(&[far_event("FA")])),
                ("CAL-B", 200, events_body(&[far_event("FB")])),
            ],
        );
        let (srv, handle, store_path, dir) =
            spawn_calendar_engine("calendar-range-once", routes, |_| {});
        let (from, to) = (iso_from_now(190), iso_from_now(210));
        // No calendar list stored yet: the command lists first.
        fetch_range(&handle, &from, &to);
        let seen = wait_for_range(&handle.evt_rx, &from, &to);
        assert!(seen.contains(&SyncEvent::CalendarUpdated), "{seen:?}");
        assert!(seen.contains(&SyncEvent::CalendarsUpdated), "{seen:?}");
        assert_eq!(view_ranges(&srv, 0, "CAL-A"), [(from.clone(), to.clone())]);
        assert_eq!(view_ranges(&srv, 0, "CAL-B"), [(from.clone(), to.clone())]);
        let store = Store::open(&store_path).unwrap();
        assert_eq!(ids_in(&store, "CAL-A"), ["FA"]);
        assert_eq!(ids_in(&store, "CAL-B"), ["FB"]);

        // Again: served from the store, no request.
        let before = srv.requests().len();
        fetch_range(&handle, &from, &to);
        let seen = wait_for_range(&handle.evt_rx, &from, &to);
        assert!(!seen.contains(&SyncEvent::CalendarUpdated), "{seen:?}");
        assert_eq!(view_requests(&srv, before, "CAL-A"), 0);
        assert_eq!(view_requests(&srv, before, "CAL-B"), 0);
        assert_eq!(calendar_requests(&srv, before), 0, "no list either");
        let _ = handle.cmd_tx.send(SyncCommand::Shutdown);
        let _ = std::fs::remove_dir_all(&dir);
    }

